import{z as A,x as B,o as r,c as d,q as s,j as t,D as e,d as n,s as i,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"股东激进主义","description":"","frontmatter":{"title":"股东激进主义","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/shareholder-activism.md","filePath":"econ/shareholder-activism.md","lastUpdated":1791413859000}'),p={name:"econ/shareholder-activism.md"};function h(m,a,D,c,T,f){const o=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=s('<h1 id="股东激进主义" tabindex="-1">股东激进主义 <a class="header-anchor" href="#股东激进主义" aria-label="Permalink to &quot;股东激进主义&quot;">​</a></h1><div class="epigraph"><p>积极股东付监测成本、积攒投票权、逼董事会改杠杆或换经理；收益部分外溢给搭便车的被动股东，因此积极主义只会不足，不会过多——除非另有私人收益。</p><footer>—— 据 Shleifer and Vishny, Large Shareholders and Corporate Control, Journal of Political Economy 1986；Brav, Jiang, Partnoy and Thomas, Journal of Finance 2008</footer></div><p><a href="/econ/executive-compensation">上一课</a>把内部合同写完。本课缺口是外部大股东与对冲基金激进主义：谁付监督成本，以及干预是价值还是转移。不重做薪酬一阶条件，不把 Grossman–Hart 要约收购提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>董事会可能被俘获，薪酬可能是租金。Shleifer–Vishny：大股东有激励监测，因为现金流权够大。代价是不分散的风险与可能的私人收益（掏空）。对冲基金激进主义是短期积攒的少数股权加公开施压、代理权争夺，不是全面收购。Brav 等描述干预手段与公告回报。缺口是：分散股权下监督是公共品，激进主义者提供公共品并试图用公告升值获利；若升值全外溢，激励不足。这与后课接管免费搭车同构，程度更轻（不必买到 100%）。</p><p><span class="marginnote">搭便车：被动指数基金享受治理改善却不付干预成本。基金业结构改变谁能当激进者。本课不写资产管理机构的微观结构。</span></p><p><span class="marginnote">数字实例：为什么监督不足。公司市值 100 亿元，激进者持股 5%。若干预让市值升 10%，其持仓升值 5000 万元，而写材料、拉票、打代理战可能要花几千万元——勉强打平。持股 0.1% 的散户对同样的升值只能分到 100 万元，绝不会亲自下场。持股越大，监测的「私人回报」才覆盖成本，这就是大股东存在的算术。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>干预菜单：要求回购与加杠杆（Jensen FCF）、换董事、分拆、换 CEO、限制并购。价值假说：降低代理成本。转移假说：把债权人、雇员、客户的准租转给股东，或短期推高股价便于减持。债务契约与评级悬崖会约束「加杠杆」菜单——债权单元刚写完。</p><p><span class="marginnote">术语翻译：「代理权争夺」（proxy fight）就是向其他股东征集委托投票权的手段来争夺董事会席位的事——你不必买下公司，只要说服多数股东把票投给你提的董事名单，就能在股东大会上换掉董事会。</span></p><p>与关系：激进主义是公开的硬信息干预；关系银行是私下。对象常是成熟、低托宾 Q、高现金——Jensen 样本，不是融资约束成长企业。</p>',11)),(r(),t(l,null,{default:e(()=>[i(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DISP%5B%22%E8%82%A1%E6%9D%83%E5%88%86%E6%95%A3%22%5D%20--%3E%20FREE%5B%22%E7%9B%91%E7%9D%A3%E5%85%AC%E5%85%B1%E5%93%81%22%5D%0A%20%20ACT%5B%22%E7%A7%AF%E6%94%92%E6%8A%95%E7%A5%A8%20%2B%20%E5%A3%B0%22%5D%20--%3E%20INT%5B%22%E5%B9%B2%E9%A2%84%22%5D%0A%20%20INT%20--%3E%20VAL%5B%22%E9%99%8D%E4%BB%A3%E7%90%86%E6%88%90%E6%9C%AC%22%5D%0A%20%20INT%20--%3E%20TRF%5B%22%E8%BD%AC%E7%A7%BB%E5%87%86%E7%A7%9F%22%5D%0A%20%20PASS%5B%22%E8%A2%AB%E5%8A%A8%E8%82%A1%E4%B8%9C%22%5D%20--%3E%20RIDE%5B%22%E6%90%AD%E4%BE%BF%E8%BD%A6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"公告正回报不自动等于社会有效：可以是转移。识别课会提事件研究的问题。本课只要两种机制并列。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是把董事会议价外移。激进股东改变董事提名池，削弱 Hermalin–Weisbach 的经理俘获。成本：错误干预、打断顾问功能、迫使削减正 NPV 的长期投资（实物期权被提前执行或放弃）。薪酬合同若已高能激励，再加外部压力可能重复或冲突。",-1)),(r(),t(l,null,{default:e(()=>[i(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20STAKE%5B%22%E5%85%88%E6%82%84%E6%82%84%E5%BB%BA%E4%BB%93%205%25-10%25%22%5D%20--%3E%20DEMAND%5B%22%E5%85%AC%E5%BC%80%E6%96%BD%E5%8E%8B%3A%20%E5%85%AC%E5%BC%80%E4%BF%A1%2F%E6%8F%90%E5%BB%BA%E8%AE%AE%22%5D%0A%20%20DEMAND%20--%3E%20NOM%5B%22%E6%8F%90%E5%90%8D%E8%87%AA%E5%B7%B1%E7%9A%84%E8%91%A3%E4%BA%8B%E5%90%8D%E5%8D%95%22%5D%0A%20%20NOM%20--%3E%20NEG%5B%22%E4%B8%8E%E8%91%A3%E4%BA%8B%E4%BC%9A%E8%B0%88%E5%88%A4%22%5D%0A%20%20NEG%20--%3E%20SETTLE%5B%22%E5%92%8C%E8%A7%A3%3A%20%E6%94%B9%E6%9D%A0%E6%9D%86%2F%E5%88%86%E6%8B%86%2F%E6%8D%A2%20CEO%22%5D%0A%20%20NEG%20--%3E%20PROXY%5B%22%E8%B0%88%E4%B8%8D%E6%8B%A2%E5%88%99%E4%BB%A3%E7%90%86%E6%9D%83%E4%BA%89%E5%A4%BA%22%5D%0A%20%20PROXY%20--%3E%20SETTLE%0A%20%20SETTLE%20--%3E%20EXIT%5B%22%E5%85%AC%E5%91%8A%E5%8D%87%E5%80%BC%E5%90%8E%E5%87%8F%E6%8C%81%E9%80%80%E5%87%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p>与择时：激进主义要求在低估时回购，像反向 Baker–Wurgler。若市场有效，回购只改切片；若无效或代理，则改 \\(V\\)。</p><h3 id="不是「基金都是短视的」" tabindex="-1">不是「基金都是短视的」 <a class="header-anchor" href="#不是「基金都是短视的」" aria-label="Permalink to &quot;不是「基金都是短视的」&quot;">​</a></h3><p>持有期数据与合约形式（13D）比标签重要。短视假说要证明被砍的是正 NPV 而不是 FCF 浪费。Tirole：可验证的派息容易被要求，不可验证的长期项目容易被牺牲——又是多任务。</p><p><span class="marginnote">Gillan–Starks 等区分公共养老基金与对冲基金的手段。机制同是投票与声，私人收益与视野不同。</span></p><p><span class="marginnote">常见误区：初学者容易把激进主义者当成纯短线炒家。实际上常见结构是先建仓、后施压：建仓在公告之前，公告正回报是干预预期兑现的结果。但注意「价值 vs 转移」两读仍然并列——回报升了不等于社会有效，可能只是把别人的准租搬进了股东口袋。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成 13D 案例集。下一课：全面接管时搭便车更致命，Grossman–Hart 给出要约必须留下利润才有人付溢价。激进主义是部分收购加语音，不是要约收购全文。</p><p>后课默认：积极股东提供公共监督，激励因搭便车而不足；干预有价值与转移两读。对象偏向 FCF 企业。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>大股东/激进基金付监测成本，被动股东搭便车，故积极主义供给不足。</li><li>菜单是杠杆、董事、资产重组；价值对转移要并列。</li><li>与内部薪酬、董事会互补，不是替代一切合同。</li><li>出处：Shleifer and Vishny, <em>JPE</em> 1986；Brav, Jiang, Partnoy and Thomas, <em>JF</em> 2008。</li></ul>',10))])}const _=A(p,[["render",h]]);export{C as __pageData,_ as default};
